    """Apply the opportunity_pipeline workflow to a record."""
    current_record = dict(record)

    def amount_positive() -> bool:
        value = current_record.get("AMT", "")
        if value is None or value == "":
            value = 0
        try:
            return float(value) > 0
        except (TypeError, ValueError):
            return False

    def close_date_present() -> bool:
        return current_record.get("CLOSE_DT", "") != "00000000"

    def has_loss_reason() -> bool:
        value = current_record.get("LOST_RSN", "")
        return isinstance(value, str) and value != ""

    transitions = [
        ("P", "qualify", amount_positive, "Q", [("set", "STAGE_PCT", "25"), ("audit", "OPP_QUAL")]),
        ("Q", "advance", lambda: True, "N", [("set", "STAGE_PCT", "60")]),
        ("N", "close_won", close_date_present, "W", [
            ("set", "STAGE_PCT", "100"),
            ("audit", "OPP_WON"),
            ("notify", "won_deal"),
        ]),
        ("P", "close_lost", has_loss_reason, "L", [
            ("set", "STAGE_PCT", "0"),
            ("audit", "OPP_LOST"),
        ]),
        ("Q", "close_lost", has_loss_reason, "L", [
            ("set", "STAGE_PCT", "0"),
            ("audit", "OPP_LOST"),
        ]),
        ("N", "close_lost", has_loss_reason, "L", [
            ("set", "STAGE_PCT", "0"),
            ("audit", "OPP_LOST"),
        ]),
    ]

    for from_state, transition_event, guard, to_state, actions in transitions:
        if state == from_state and event == transition_event and guard():
            audits = []
            notifies = []
            result_record = dict(current_record)

            for action in actions:
                if action[0] == "set":
                    result_record[action[1]] = action[2]
                elif action[0] == "audit":
                    audits.append(action[1])
                elif action[0] == "notify":
                    notifies.append(action[1])

            return {
                "state": to_state,
                "record": result_record,
                "audits": audits,
                "notifies": notifies,
                "matched": True,
            }

    return {
        "state": state,
        "record": current_record,
        "audits": ["WF_NOMATCH"],
        "notifies": [],
        "matched": False,
    }
